"Set aside time for silent prayer, meditation, or a Holy Hour, with a gentle bell to begin and end.": "Reserva un tiempo para la oración en silencio, la meditación o una Hora Santa, con una campana suave al empezar y al terminar.",
"Test what you know about the saints, Scripture, Church history, and great Catholic books.": "Pon a prueba lo que sabes de los santos, la Escritura, la historia de la Iglesia y los grandes libros católicos.",
"Every prayer as an illustrated prayer card. Choose a topic, then open a card to pray it, save it, or print it.": "Cada oración como una estampa ilustrada. Elige un tema y abre una estampa para rezarla, guardarla o imprimirla.",
"The prayer St. Ignatius never wanted his companions to skip: five short steps to look back on the day with God.": "La oración que san Ignacio nunca quiso que sus compañeros omitieran: cinco pasos breves para repasar el día con Dios.",
"Gregorian chant and beloved Catholic hymns, with recordings and the words in Latin and English: the Salve Regina, Pange Lingua, Veni Creator, Adeste Fideles, and more.": "Canto gregoriano y queridos himnos católicos, con grabaciones y la letra en latín e inglés: la Salve Regina, Pange Lingua, Veni Creator, Adeste Fideles y más.",
"The Hours of Our Lady, from Matins to Compline, following the seasons of the year. A beloved prayer of religious, tertiaries, and those who wear the Brown Scapular.": "Las Horas de Nuestra Señora, de Maitines a Completas, según los tiempos del año. Una oración querida por religiosos, terciarios y quienes llevan el escapulario del Carmen.",
"The Brown and Green Scapulars, the Miraculous and St. Benedict Medals, First Fridays and First Saturdays, and holy water: what each one is, how to keep it, and its prayers.": "Los escapularios del Carmen y verde, la Medalla Milagrosa y la de San Benito, los primeros viernes y primeros sábados, y el agua bendita: qué es cada uno, cómo vivirlo y sus oraciones.",
"The ancient prayer of the Incarnation, prayed at morning, noon, and evening. During the Easter season, the Regina Caeli.": "La antigua oración de la Encarnación, rezada por la mañana, al mediodía y por la tarde. En el tiempo pascual, el Regina Caeli.",
"Pray with a passage of Scripture the way the monks did: read, reflect, respond, and rest in God.": "Reza con un pasaje de la Escritura como lo hacían los monjes: lee, medita, responde y descansa en Dios.",
"Keep a private record of your daily prayer, build a steady habit, and see your faithfulness over the weeks.": "Lleva un registro privado de tu oración diaria, crea un hábito constante y mira tu fidelidad a lo largo de las semanas.",
"Every part of the Mass in order, with when to stand, sit, and kneel, and what each moment means. Follow along on your phone at Mass.": "Cada parte de la Misa en orden, con cuándo ponerse de pie, sentarse y arrodillarse, y qué significa cada momento. Síguela en tu teléfono durante la Misa.",
"Every pope from St. Peter to Leo XIV, century by century.": "Todos los papas, de san Pedro a León XIV, siglo a siglo.",
"The great religious orders of the Church: monks, canons, friars, clerks regular, sisters, and the military orders of the crusades.": "Las grandes órdenes religiosas de la Iglesia: monjes, canónigos, frailes, clérigos regulares, religiosas y las órdenes militares de las cruzadas.",
"The most famous icons of East and West, what they show, and the stories behind them.": "Los iconos más famosos de Oriente y Occidente, lo que representan y sus historias.",
"The twenty-three Eastern Catholic Churches, in full communion with Rome: their traditions, leaders, and lands.": "Las veintitrés Iglesias católicas orientales, en plena comunión con Roma: sus tradiciones, sus pastores y sus tierras.",
"How to become Catholic or come home, the basics of everyday Catholic life, and guides to discerning and living each vocation: marriage, priesthood, religious life, and more.": "Cómo hacerse católico o volver a casa, lo básico de la vida católica cotidiana y guías para discernir y vivir cada vocación: matrimonio, sacerdocio, vida religiosa y más.",
"The lists every Catholic learns, explained: the Ten Commandments, the Beatitudes, the precepts, the sacraments, the virtues, the works of mercy, the capital sins, and more.": "Las listas que todo católico aprende, explicadas: los Diez Mandamientos, las Bienaventuranzas, los preceptos, los sacramentos, las virtudes, las obras de misericordia, los pecados capitales y más.",
"A walk through a Catholic church: what each part is for, the sacred vessels, the vestments, the colors of the seasons, and how to take part in the Mass.": "Un recorrido por una iglesia católica: para qué sirve cada parte, los vasos sagrados, las vestiduras, los colores de cada tiempo y cómo participar en la Misa.",
"All twenty-one ecumenical councils, from Nicaea to Vatican II: when and where they met, and what each one taught.": "Los veintiún concilios ecuménicos, de Nicea al Vaticano II: cuándo y dónde se reunieron y qué enseñó cada uno.",
"Clear, short definitions of the words of the Catholic faith, from Absolution to the Vulgate.": "Definiciones breves y claras de las palabras de la fe católica, de «absolución» a «Vulgata».",
"The words of the saints, from the Church Fathers to our own day, each with its source. Search them, browse by theme, and share your favorites.": "Las palabras de los santos, de los Padres de la Iglesia a nuestros días, cada una con su fuente. Búscalas, explóralas por tema y comparte tus favoritas.",
"Pick as many answers as you like: your name, your work, your needs, and what you love in a saint. Sanctify suggests friends in heaven who fit.": "Elige tantas respuestas como quieras: tu nombre, tu trabajo, tus necesidades y lo que más admiras en un santo. Sanctify te sugiere amigos en el cielo a tu medida.",
