"{n} common objections answered": "{n} objeciones frecuentes respondidas",
"Apologetics: the reasons behind the faith, and charitable answers to the questions and objections Catholics most often hear.": "Apologética: las razones de la fe y respuestas caritativas a las preguntas y objeciones que más oyen los católicos.",
"Simple Words": "En palabras sencillas",
"Ten questions drawn at random from the saints, books, Church history, the Bible, and theology on Sanctify. Every quiz is different.": "Diez preguntas al azar sobre los santos, los libros, la historia de la Iglesia, la Biblia y la teología de Sanctify. Cada cuestionario es distinto.",
"Start the quiz": "Empezar el cuestionario",
"Lives, feast days, patronages, and prayers of intercession, from the apostles to saints of our own time. Browse by era and walk of life, or search by what they are patrons of.": "Vidas, fiestas, patronazgos y oraciones de intercesión, desde los apóstoles hasta los santos de nuestro tiempo. Explora por época y estado de vida, o busca por aquello de lo que son patronos.",
