"Pray the Rosary bead by bead with the fifteen traditional mysteries, Joyful, Sorrowful, and Glorious, and a meditation for each.": "Reza el Rosario cuenta a cuenta con los quince misterios tradicionales, gozosos, dolorosos y gloriosos, y una meditación para cada uno.",
