"The encyclopedia Sanctify members write together: parishes and shrines, devotions, local customs, how-tos, and anything else worth knowing. Anyone with a free account can start or improve a page, and every change is kept.": "La enciclopedia que escriben juntos los miembros de Sanctify: parroquias y santuarios, devociones, costumbres locales, guías prácticas y todo lo que valga la pena saber. Cualquiera con una cuenta gratuita puede crear o mejorar una página, y se guarda cada cambio.",
